  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fillBleed(0.2);
  brush.fill("#8fc1e3", 170);
  brush.beginShape(0.3);
  brush.vertex(0, 0); brush.vertex(400, 0); brush.vertex(400, 200); brush.vertex(0, 200);
  brush.endShape(true);
  brush.fill("#f6d36b", 220);
  brush.circle(310, 70, 30);
  brush.fill("#7a9a6b", 180);
  brush.beginShape(0.5);
  brush.vertex(0, 200); brush.vertex(120, 170); brush.vertex(260, 185); brush.vertex(400, 165); brush.vertex(400, 215); brush.vertex(0, 215);
  brush.endShape(true);
  brush.fill("#9db86a", 190);
  brush.beginShape(0.2);
  brush.vertex(0, 205); brush.vertex(400, 205); brush.vertex(400, 400); brush.vertex(0, 400);
  brush.endShape(true);
  for (let i = 0; i < 9; i++) {
    let w = 10 + i * 8;
    let tx = 200 + (i - 4) * 12;
    let bx = 200 + (i - 4) * 70;
    brush.fill(i % 2 ? "#8a6bbf" : "#a585d6", 200);
    brush.beginShape(0.2);
    brush.vertex(tx - 3, 210); brush.vertex(tx + 3, 210);
    brush.vertex(constrain(bx + w / 2, 0, 400), 400); brush.vertex(constrain(bx - w / 2, 0, 400), 400);
    brush.endShape(true);
  }
  brush.fill("#5a7a3a", 200);
  brush.beginShape(0.6);
  brush.vertex(60, 175); brush.vertex(80, 140); brush.vertex(100, 175);
  brush.endShape(true);
  brush.fill("#6a4a9a", 160);
  for (let i = 0; i < 25; i++) {
    brush.circle(random(0, 400), random(320, 395), random(4, 9));
  }
}
