}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fillBleed(0.2);
  brush.fill("#cfe0c8", 160);
  brush.beginShape(0.3);
  brush.vertex(0, 0); brush.vertex(400, 0); brush.vertex(400, 230); brush.vertex(0, 230);
  brush.endShape(true);
  brush.fill("#e9d58a", 140);
  brush.circle(130, 110, 120);
  brush.circle(300, 90, 100);
  brush.fill("#8fae6a", 190);
  brush.beginShape(0.3);
  brush.vertex(0, 210); brush.vertex(400, 200); brush.vertex(400, 400); brush.vertex(0, 400);
  brush.endShape(true);
  brush.fill("#c9a878", 210);
  brush.beginShape(0.6);
  brush.vertex(190, 215); brush.vertex(215, 215); brush.vertex(260, 300);
  brush.vertex(300, 400); brush.vertex(110, 400); brush.vertex(170, 300);
  brush.endShape(true);
  let trees = [[40, 18], [100, 12], [150, 8], [255, 8], [300, 13], [360, 20], [20, 10]];
  for (let t of trees) {
    let x = t[0], w = t[1];
    brush.fill("#f7f4ee", 240);
    brush.beginShape(0.1);
    brush.vertex(x - w / 2, 0); brush.vertex(x + w / 2, 0);
    brush.vertex(x + w / 2 + 2, 210 + w * 6); brush.vertex(x - w / 2 - 2, 210 + w * 6);
    brush.endShape(true);
    for (let y = 30; y < 200 + w * 6; y += 40) {
      brush.fill("#2e2a26", 200);
      brush.beginShape(0.5);
      brush.vertex(x - w / 2, y); brush.vertex(x + w / 4, y + 3); brush.vertex(x - w / 2, y + 7);
      brush.endShape(true);
    }
  }
  brush.fill("#d98c3a", 150);
  brush.circle(80, 40, 35); brush.circle(320, 50, 40); brush.circle(200, 30, 30);
