    brush.vertex(200 + cos(t) * r, 270 + sin(t) * r);
  }
  for (let a = 12; a >= 0; a--) {
    let t = PI + (PI * a) / 12;
    brush.vertex(200 + cos(t) * (r - w), 270 + sin(t) * (r - w));
